import { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';

export default function Dashboard() {
  const navigate = useNavigate();
  const [user, setUser] = useState(null);
  const [sessions, setSessions] = useState([]);
  const [loading, setLoading] = useState(true);
  const [showAchievement, setShowAchievement] = useState(false);
  const [activeView, setActiveView] = useState('dashboard'); // 'dashboard' or 'history'
  const [filterSubject, setFilterSubject] = useState('all');
  const [searchTerm, setSearchTerm] = useState('');
  const [studyGoal, setStudyGoal] = useState(localStorage.getItem('studyGoal') || '10');
  const [quickNote, setQuickNote] = useState('');

  useEffect(() => {
    loadUserData();
    loadSessions();
  }, []);

  useEffect(() => {
    if (sessions.length >= 5 && !localStorage.getItem('achievement_5sessions')) {
      setShowAchievement(true);
      localStorage.setItem('achievement_5sessions', 'true');
      setTimeout(() => setShowAchievement(false), 5000);
    }
  }, [sessions.length]);

  const loadUserData = () => {
    const userData = localStorage.getItem('currentUser');
    if (userData) {
      setUser(JSON.parse(userData));
    }
  };

  const loadSessions = async () => {
    try {
      const token = localStorage.getItem('authToken');
      if (!token) {
        console.log('No token found');
        setLoading(false);
        return;
      }

      const response = await fetch('http://localhost:8000/api/sessions', {
        headers: {
          'Authorization': `Bearer ${token}`,
          'Content-Type': 'application/json'
        }
      });

      if (response.ok) {
        const data = await response.json();
        console.log('✅ Sessions loaded:', data);
        setSessions(data);
      } else {
        console.error('❌ Failed to load sessions:', response.status);
      }
    } catch (error) {
      console.error('❌ Error loading sessions:', error);
    } finally {
      setLoading(false);
    }
  };

  const handleLogout = () => {
    localStorage.clear();
    navigate('/auth', { replace: true });
  };

  const handleStartSession = (tutorId, subject) => {
    const roomId = `room_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`;
    console.log('🚀 Starting NEW session with tutorId:', tutorId, 'subject:', subject);
    navigate(`/video/${roomId}`, { 
      state: { 
        tutorId: tutorId, 
        subject: subject, 
        resuming: false 
      },
      replace: true
    });
  };

  const handleResumeSession = (session) => {
    navigate(`/video/${session.session_id}`, { 
      state: { 
        tutorId: session.tutor_id,
        subject: session.subject, 
        resuming: true 
      },
      replace: true
    });
  };

  const handleSaveGoal = () => {
    localStorage.setItem('studyGoal', studyGoal);
    alert('Study goal saved!');
  };

  const handleSaveNote = () => {
    if (!quickNote.trim()) return;
    const notes = JSON.parse(localStorage.getItem('quickNotes') || '[]');
    notes.unshift({
      id: Date.now(),
      text: quickNote,
      date: new Date().toISOString()
    });
    localStorage.setItem('quickNotes', JSON.stringify(notes.slice(0, 10))); // Keep last 10
    setQuickNote('');
    alert('Note saved!');
  };

  const tutors = [
    { 
      id: 'omkar_ai',
      name: 'Omkar', 
      subject: 'AI & Machine Learning', 
      description: 'Expert in Artificial Intelligence and Machine Learning', 
      specialty: 'Neural Networks, Deep Learning, NLP',
      rating: 4.9,
      students: 234
    },
    { 
      id: 'priya_biology',
      name: 'Priya', 
      subject: 'Biology', 
      description: 'Passionate Biology tutor specializing in life sciences', 
      specialty: 'Genetics, Cell Biology, Physiology',
      rating: 4.8,
      students: 189
    }
  ];

  const calculateStudyHours = () => {
    const totalMinutes = sessions.reduce((sum, session) => {
      return sum + 30; // 30 mins per session average
    }, 0);
    return (totalMinutes / 60).toFixed(1);
  };

  const streak = Math.min(sessions.length, 7);
  const totalHours = calculateStudyHours();

  const subjectStats = sessions.reduce((acc, session) => {
    const subject = session.tutor_id === 'omkar_ai' ? 'AI & ML' : 'Biology';
    acc[subject] = (acc[subject] || 0) + 1;
    return acc;
  }, {});

  const filteredSessions = sessions.filter(session => {
    const matchesSubject = filterSubject === 'all' || 
      (filterSubject === 'ai' && session.tutor_id === 'omkar_ai') ||
      (filterSubject === 'bio' && session.tutor_id === 'priya_biology');

    const matchesSearch = searchTerm === '' || 
      session.tutor_id.toLowerCase().includes(searchTerm.toLowerCase());

    return matchesSubject && matchesSearch;
  });

  const getLast7DaysActivity = () => {
    const last7Days = Array.from({ length: 7 }, (_, i) => {
      const date = new Date();
      date.setDate(date.getDate() - (6 - i));
      return date.toISOString().split('T')[0];
    });

    return last7Days.map(date => {
      const count = sessions.filter(s => 
        new Date(s.created_at).toISOString().split('T')[0] === date
      ).length;
      return { date, count };
    });
  };

  const weeklyActivity = getLast7DaysActivity();

  // Get topics covered (simulated - in real app, extract from session data)
  const topicsCovered = [
    { subject: 'AI & ML', topics: ['Neural Networks', 'Supervised Learning', 'Model Training'] },
    { subject: 'Biology', topics: ['Cell Structure', 'DNA Replication', 'Photosynthesis'] }
  ].filter(item => subjectStats[item.subject]);

  // Learning recommendations based on history
  const getRecommendations = () => {
    const aiCount = subjectStats['AI & ML'] || 0;
    const bioCount = subjectStats['Biology'] || 0;

    const recommendations = [];
    if (aiCount > bioCount) {
      recommendations.push({ tutor: 'Priya', subject: 'Biology', reason: 'Balance your learning' });
    } else if (bioCount > aiCount) {
      recommendations.push({ tutor: 'Omkar', subject: 'AI & ML', reason: 'Balance your learning' });
    }

    if (sessions.length >= 3) {
      recommendations.push({ 
        tutor: sessions[sessions.length - 1].tutor_id === 'omkar_ai' ? 'Omkar' : 'Priya', 
        subject: sessions[sessions.length - 1].tutor_id === 'omkar_ai' ? 'AI & ML' : 'Biology',
        reason: 'Continue your last topic' 
      });
    }

    return recommendations;
  };

  const recommendations = getRecommendations();

  const renderHistoryView = () => (
    <div className="p-8">
      <div className="mb-8">
        <h2 className="text-3xl font-bold text-slate-100 mb-2">Session History</h2>
        <p className="text-slate-400">View and manage all your past learning sessions</p>
      </div>

      {/* Filters */}
      <div className="flex items-center justify-between mb-6 gap-4">
        <div className="relative flex-1 max-w-md">
          <input
            type="text"
            placeholder="Search sessions..."
            value={searchTerm}
            onChange={(e) => setSearchTerm(e.target.value)}
            className="w-full pl-10 pr-4 py-3 bg-slate-800 border border-slate-700 rounded-lg text-sm text-slate-200 placeholder-slate-500 focus:outline-none focus:ring-2 focus:ring-slate-600"
          />
